mapper.select:
SELECT

FROM
    dm_ai_session
WHERE
    puid = #{puid}
    AND
    uid  = #{uid}

    AND
    (
        gmt_modified  <  #{beforeModifiedAt}
        OR
        (
            gmt_modified = #{beforeModifiedAt}
            AND
            session_id  <  #{beforeId}
        )
    )


    AND
    (
        title LIKE CONCAT('%', #{keyword}, '%')
        OR
        (
            title IS NULL
            AND
            engine_name LIKE CONCAT('%', #{keyword}, '%')
        )
    )

ORDER BY
    gmt_modified DESC,
    session_id DESC
LIMIT #{limit}

mapper.update:
UPDATE
    dm_ai_session
SET
    gmt_modified = #{gmtModified}
WHERE
    session_id = #{id}
